  });

  it('critério 7: conta com transações não pode ser excluída; sem transações pode', () => {
    const estado = construirEstado({
      contas: [conta({ id: 'a' }), conta({ id: 'b' })],
      transacoes: [transacao({ id: '1', contaId: 'a' })],
    });
