    ['Categoria', c.base, c.comparado, 'Diferença', 'Variação (%)'],
    ...c.linhas.map((l) => [l.nome, numeroCsv(l.valorBase), numeroCsv(l.valorComparado), numeroCsv(l.diferenca), percentualCsv(l.variacao)]),
